def node_fp(f, nid):
    seg=f.segmentation; n=seg['nodes'][nid]
    cells=set()
    a=f.ascii.split('\n')
    b=n['boundary']; bb=(min(p[0] for p in b),min(p[1] for p in b),max(p[0] for p in b),max(p[1] for p in b))
    for cid in n['children']:
        cb=seg['nodes'][cid]['boundary']
        for (r,c) in cb: cells.add((r,c))
    for r in range(bb[0],bb[2]+1):
        for c in range(bb[1],bb[3]+1):
